1: import { type Request, type Response } from 'express'
2: import * as challengeUtils from '../lib/challengeUtils'
3: import * as utils from '../lib/utils'
4: import { challenges } from '../data/datacache'
5: 
6: export function checkKeys () {
7:   return async (req: Request, res: Response) => {
8:     try {
9:       const { HDNodeWallet } = await import('ethers')
10:       const mnemonic = 'purpose betray marriage blame crunch monitor spin slide donate sport lift clutch'
11:       const mnemonicWallet = HDNodeWallet.fromPhrase(mnemonic)
12:       const privateKey = mnemonicWallet.privateKey
13:       const publicKey = mnemonicWallet.publicKey
14:       const address = mnemonicWallet.address
15:       challengeUtils.solveIf(challenges.nftUnlockChallenge, () => {
16:         return req.body.privateKey === privateKey
17:       })
18:       if (req.body.privateKey === privateKey) {
19:         res.status(200).json({ success: true, message: 'Challenge successfully solved', status: challenges.nftUnlockChallenge })
20:       } else {
21:         if (req.body.privateKey === address) {
22:           res.status(401).json({ success: false, message: 'Looks like you entered the public address of my ethereum wallet!', status: challenges.nftUnlockChallenge })
23:         } else if (req.body.privateKey === publicKey) {
24:           res.status(401).json({ success: false, message: 'Looks like you entered the public key of my ethereum wallet!', status: challenges.nftUnlockChallenge })
25:         } else {
26:           res.status(401).json({ success: false, message: 'Looks like you entered a non-Ethereum private key to access me.', status: challenges.nftUnlockChallenge })
27:         }
28:       }
29:     } catch (error) {
30:       res.status(500).json(utils.getErrorMessage(error))
31:     }
32:   }
33: }
