12: export function imageCaptchas () {
13:   return async (req: Request, res: Response) => {
14:     try {
15:       const { default: svgCaptcha } = await import('svg-captcha')
16:       const captcha = svgCaptcha.create({ size: 5, noise: 2, color: true })
17: 
18:       const user = security.authenticatedUsers.from(req)
19:       if (!user) {
20:         res.status(401).send(res.__('You need to be logged in to request a CAPTCHA.'))
21:         return
22:       }
23: 
24:       const imageCaptcha = {
25:         image: captcha.data,
26:         answer: captcha.text,
27:         UserId: user.data.id
28:       }
29:       const imageCaptchaInstance = ImageCaptchaModel.build(imageCaptcha)
30:       await imageCaptchaInstance.save()
31:       res.json(imageCaptcha)
32:     } catch (error) {
33:       res.status(400).send(res.__('Unable to create CAPTCHA. Please try again.'))
34:     }
35:   }
36: }
